const int motionPin = 2;
const int ledPin = 13;
const int buzzerPin = 8;

bool alarmActive = false;
unsigned long lastTriggerTime = 0;
const unsigned long alarmDuration = 3000;      // сколько секунд работает сигнал
const unsigned long cooldown = 10000;         // пауза перед повторным срабатыванием

void setup() {
  pinMode(motionPin, INPUT);
  pinMode(ledPin, OUTPUT);
  pinMode(buzzerPin, OUTPUT);
  digitalWrite(ledPin, LOW);
  digitalWrite(buzzerPin, LOW);
}

void loop() {
  int motionState = digitalRead(motionPin);

  if (motionState == HIGH && !alarmActive) {
    alarmActive = true;
    lastTriggerTime = millis();
  }

  unsigned long now = millis();

  if (alarmActive) {
    if (now - lastTriggerTime < alarmDuration) {
      digitalWrite(ledPin, HIGH);
      digitalWrite(buzzerPin, HIGH);
    } else {
      // сигнал закончился, ждём cooldown
      digitalWrite(ledPin, LOW);
      digitalWrite(buzzerPin, LOW);

      if (now - lastTriggerTime >= cooldown) {
        alarmActive = false; // можно снова реагировать
      }
    }
  } else {
    digitalWrite(ledPin, LOW);
    digitalWrite(buzzerPin, LOW);
  }
}
